return [{
  json: {
    executionMode: 'synthetic-manual',
    notice: {
      noticeKey: 'SYN-REVIEW-001',
      title: '[합성] 비영리 직접생산 예외 검토 용역',
      agency: '가상 발주기관',
      deadline: '2026-08-31T18:00:00+09:00',
      estimatedAmount: 200000000
    },
    assessment: {
      documentStatus: 'COMPLETE',
      eligibility: 'REVIEW',
      reasonCode: 'R01',
      defaultFail: false,
      readinessScore: 92,
      readinessStatus: 'GREEN',
      evidenceCoverage: 100,
      riskScore: 40.8,
      riskBand: 'CONDITIONAL_GO',
      atomicResults: [{
        label: '직접생산확인증명서 예외 검토',
        result: 'REVIEW',
        reason_code: 'R01',
        message: '발주처의 서면 확인이 필요합니다.'
      }]
    }
  }
}];

const input = $json ?? {};
const noticeSource = input.notice && typeof input.notice === 'object' ? input.notice : input;
const assessmentSource = input.assessment && typeof input.assessment === 'object'
  ? input.assessment
  : (input.latest_evaluation ?? {});
const noticeKey = String(noticeSource.noticeKey ?? noticeSource.notice_key ?? '').trim().slice(0, 160);
const title = String(noticeSource.title ?? '').trim().slice(0, 500);
if (!noticeKey || !title) throw new Error('noticeKey and title are required');
const eligibility = String(assessmentSource.eligibility ?? '').toUpperCase();
if (!['PASS', 'REVIEW', 'FAIL'].includes(eligibility)) {
  throw new Error('assessment.eligibility must be PASS, REVIEW, or FAIL');
}
let apiBaseUrlRaw = '';
let dashboardUrlRaw = '';
try {
  apiBaseUrlRaw = String($env.PAI_LOOP_API_BASE_URL ?? '').trim();
  dashboardUrlRaw = String($env.PAI_LOOP_DASHBOARD_URL ?? '').trim();
} catch {
  apiBaseUrlRaw = '';
  dashboardUrlRaw = '';
}
const safeUrl = (raw, label, allowEmpty) => {
  if (!raw && allowEmpty) return '';
  let parsed;
  try { parsed = new URL(raw); } catch { throw new Error(`${label} must be an absolute HTTP(S) URL`); }
  if (!['http:', 'https:'].includes(parsed.protocol) || parsed.username || parsed.password) {
    throw new Error(`${label} must use HTTP(S) without embedded credentials`);
  }
  return parsed.toString().replace(/\/+$/, '');
};
const apiBaseUrl = safeUrl(apiBaseUrlRaw, 'PAI_LOOP_API_BASE_URL', true);
const dashboardBaseUrl = safeUrl(
  dashboardUrlRaw || 'https://example.invalid/pai-loop',
  'PAI_LOOP_DASHBOARD_URL',
  false
);
const noticeUrl = `${dashboardBaseUrl}/notices/${encodeURIComponent(noticeKey)}`;
const atomicResults = Array.isArray(assessmentSource.atomicResults)
  ? assessmentSource.atomicResults
  : (Array.isArray(assessmentSource.atomic_results) ? assessmentSource.atomic_results : []);
const reasonCode = String(assessmentSource.reasonCode ?? assessmentSource.reason_code ?? 'UNSPECIFIED').slice(0, 32);
const correlationId = `teams-mock:${noticeKey.slice(0, 70)}:${new Date().toISOString()}`;
return [{
  json: {
    runtime: { apiBaseUrl, backendMockConfigured: apiBaseUrl.length > 0 },
    correlationId,
    notice: {
      noticeKey,
      title,
      agency: String(noticeSource.agency ?? '미상').slice(0, 255),
      deadline: noticeSource.deadline ?? null,
      estimatedAmount: noticeSource.estimatedAmount ?? noticeSource.estimated_amount ?? null,
      noticeUrl
    },
    assessment: {
      eligibility,
      reasonCode,
      defaultFail: eligibility === 'FAIL' && reasonCode === 'DF-000',
      readinessScore: Number(assessmentSource.readinessScore ?? assessmentSource.readiness_score ?? 0),
      readinessStatus: String(assessmentSource.readinessStatus ?? assessmentSource.readiness_status ?? 'GRAY'),
      evidenceCoverage: Number(assessmentSource.evidenceCoverage ?? assessmentSource.evidence_coverage ?? 0),
      riskScore: assessmentSource.riskScore ?? assessmentSource.risk_score ?? null,
      riskBand: String(assessmentSource.riskBand ?? assessmentSource.risk_band ?? 'UNKNOWN'),
      atomicResults
    }
  }
}];

const input = $json;
const notice = input.notice;
const assessment = input.assessment;
const won = new Intl.NumberFormat('ko-KR').format(Number(notice.estimatedAmount ?? 0));
const eligibilityColor = assessment.eligibility === 'PASS' ? 'good' : (assessment.eligibility === 'FAIL' ? 'attention' : 'warning');
const topEvidence = assessment.atomicResults.slice(0, 3).map((item) => ({
  type: 'TextBlock',
  text: `• ${String(item.label ?? item.requirement_key ?? '판정 근거')}: ${String(item.message ?? item.result ?? '')}`,
  wrap: true,
  spacing: 'Small',
  size: 'Small'
}));
const adaptiveCard = {
  '$schema': 'http://adaptivecards.io/schemas/adaptive-card.json',
  type: 'AdaptiveCard',
  version: '1.5',
  msteams: { width: 'Full' },
  body: [
    { type: 'TextBlock', text: 'PAI_LOOP · 신규 검토 공고', weight: 'Bolder', size: 'Large', color: 'Accent', wrap: true },
    { type: 'TextBlock', text: notice.title, weight: 'Bolder', size: 'Medium', wrap: true, spacing: 'Medium' },
    {
      type: 'FactSet',
      facts: [
        { title: '발주기관', value: notice.agency },
        { title: '마감일', value: String(notice.deadline ?? '미정') },
        { title: '추정금액', value: `${won}원` },
        { title: '참가자격', value: assessment.eligibility },
        { title: '사유코드', value: assessment.reasonCode },
        { title: '준비도', value: `${assessment.readinessStatus} (${assessment.readinessScore})` },
        { title: '리스크', value: `${assessment.riskBand}${assessment.riskScore == null ? '' : ` (${assessment.riskScore})`}` }
      ]
    },
    {
      type: 'Container',
      style: eligibilityColor,
      bleed: true,
      items: [
        { type: 'TextBlock', text: assessment.eligibility === 'REVIEW' ? '사람의 확인이 필요합니다' : '자동 알림 요약', weight: 'Bolder', wrap: true },
        ...topEvidence
      ]
    },
    {
      type: 'TextBlock',
      text: '이 카드는 의사결정 보조 정보입니다. 최종 입찰 판단은 원문과 증빙을 확인한 담당자가 기록합니다.',
      wrap: true,
      isSubtle: true,
      size: 'Small',
      spacing: 'Medium'
    }
  ],
  actions: [
    { type: 'Action.OpenUrl', title: '근거와 상세 보기', url: notice.noticeUrl }
  ]
};
const teamsWebhookPayload = {
  type: 'message',
  attachments: [{
    contentType: 'application/vnd.microsoft.card.adaptive',
    contentUrl: null,
    content: adaptiveCard
  }]
};
return [{
  json: {
    ...input,
    delivery: { channel: 'teams', mode: 'mock', boundaryVersion: '1.0' },
    adaptiveCard,
    teamsWebhookPayload
  }
}];

const input = $json;
return [{
  json: {
    ...input,
    mockLog: {
      id: `mock-local-${input.correlationId.replace(/[^a-zA-Z0-9_-]/g, '-').slice(0, 100)}`,
      notice_key: input.notice.noticeKey,
      channel: 'teams',
      delivery_mode: 'mock',
      status: 'MOCK_RECORDED',
      card: input.adaptiveCard,
      correlation_id: input.correlationId,
      created_at: new Date().toISOString()
    }
  }
}];

const input = $json ?? {};
const record = input.body && typeof input.body === 'object'
  ? input.body
  : (input.mockLog ?? input);
const card = record.card ?? input.adaptiveCard;
if (!card || card.type !== 'AdaptiveCard' || card.version !== '1.5' || !Array.isArray(card.body)) {
  throw new Error('Mock result must contain a valid Adaptive Card 1.5 body');
}
const cardBytes = new TextEncoder().encode(JSON.stringify(card)).length;
if (cardBytes > 28 * 1024) throw new Error('Adaptive Card exceeds the Teams 28KB limit');
if (!Array.isArray(card.actions) || !card.actions.every((action) => action.type === 'Action.OpenUrl')) {
  throw new Error('Adaptive Card actions must be Action.OpenUrl only');
}
for (const action of card.actions) {
  const url = new URL(action.url);
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) {
    throw new Error('Adaptive Card action URL is unsafe');
  }
}
const channel = String(record.channel ?? 'teams').toLowerCase();
const deliveryMode = String(record.delivery_mode ?? 'mock').toLowerCase();
const status = String(record.status ?? 'MOCK_RECORDED');
if (channel !== 'teams' || deliveryMode !== 'mock') {
  throw new Error('Mock log channel/mode must be teams/mock');
}
if (status !== 'MOCK_RECORDED') throw new Error('Mock log status must be MOCK_RECORDED');
return [{
  json: {
    schemaVersion: '1.0',
    notification: {
      id: String(record.id ?? ''),
      noticeKey: String(record.notice_key ?? input.notice?.noticeKey ?? ''),
      channel,
      deliveryMode,
      status,
      correlationId: String(record.correlation_id ?? input.correlationId ?? ''),
      createdAt: record.created_at ?? new Date().toISOString()
    },
    adaptiveCard: card,
    teamsWebhookPayload: input.teamsWebhookPayload ?? {
      type: 'message',
      attachments: [{ contentType: 'application/vnd.microsoft.card.adaptive', contentUrl: null, content: card }]
    },
    actualTeamsRequestSent: false
  }
}];
